{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C05", "C11", "C01", "C12", "C123", "C138", "C06"],
  "contradictory_card_ids": ["C31"],
  "prediction_basis_card_ids": ["C05", "C11", "C01", "C12", "C123", "C138"],
  "claims": [
    {
      "claim": "Pethidine shares the query's 4-arylpiperidine core and had systemic availability 0.80 ± 0.15 in cirrhosis and about 0.48 in normal subjects, both well above 20%.",
      "card_ids": ["C05", "C19", "C23", "C47"]
    },
    {
      "claim": "Setipiprant, a carboxylic acid drug, had human F of at least 50% and rat and dog F of 44% and 55%, showing the acid group does not preclude F ≥ 20%.",
      "card_ids": ["C11", "C27", "C34", "C36"]
    },
    {
      "claim": "Odanacatib, containing nitrile and fluorophenyl motifs, had absolute F of 70% at 10 mg and 30% at 50 mg, both above threshold.",
      "card_ids": ["C01", "C02", "C09"]
    },
    {
      "claim": "Maraviroc fasted F was 24% at 100 mg and 33% at 600 mg, above threshold; dose dependence does not create affirmative low evidence.",
      "card_ids": ["C12", "C22", "C44", "C50"]
    },
    {
      "claim": "L4 fexofenadine records show a zwitterion with human in situ Peff of 2.61 × 10^-5 cm/s and rat Peff of 7.04 × 10^-6 cm/s, demonstrating measurable intestinal permeability despite zwitterionic character; haloperidol Caco-2 Papp of 14.5 × 10^-6 cm/s and loperamide FA of 65-100% support absorption of piperidine-aryl drugs, and haloperidol F was 35 ± 8% in the L1 context.",
      "card_ids": ["C123", "C106", "C150", "C138", "C108", "C143", "C06"]
    },
    {
      "claim": "The only sub-20% F record, ampicillin in veal calves at 12%, is species-specific and not transferable to the human query prediction.",
      "card_ids": ["C31"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C123", "C106", "C150", "C138", "C143", "C108", "C121", "C119"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query; prediction remains transfer-based.",
    "L4 records provide permeability and solubility for analogs, not the query itself; no query-specific experimental permeability or solubility data exist.",
    "Query condition is unspecified; many high-F contexts are fasted or cirrhosis, and pethidine normal F of about 0.48 is above threshold but not an exact condition match.",
    "L3 exposure records lack IV comparators, so they show oral absorption but do not quantify F directly.",
    "Odanacatib and maraviroc F are dose-dependent, so quantitative transfer is uncertain.",
    "Gut-wall efflux and intestinal metabolism (L5) are not yet assessed; fexofenadine is a P-gp substrate and the query's zwitterionic permeability may be transporter-limited."
  ],
  "decision_summary": "L4 intestinal absorption and permeability records show that zwitterionic acids such as fexofenadine have measurable human intestinal permeability (Peff 2.61 × 10^-5 cm/s) and that piperidine-containing drugs such as haloperidol and loperamide are well absorbed, with haloperidol F of 35 ± 8% in the L1 context. These records support the absorption component of the query despite its low logD and zero neutral fraction. Combined with L1/L2 transferable F evidence (pethidine, setipiprant, odanacatib, maraviroc, meptazinol, haloperidol, ketanserin, glasdegib) all above 20%, and with the only sub-20% record being species-specific calf ampicillin, the prediction remains high with moderate confidence."
}

